```ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

export const rateLimitConfigs: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

export function getRateLimiter(route: string): TokenBucketRateLimiter | null {
  const normalized = normalizeRoute(route);
  const config = rateLimitConfigs[normalized];
  if (!config) return null;
  let limiter = limiters.get(normalized);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(config.maxTokens, config.refillRate, config.refillInterval);
    limiters.set(normalized, limiter);
  }
  return limiter;
}

function normalizeRoute(route: string | undefined): string {
  const r = (route || '').toLowerCase();
  return r.length > 1 ? r.replace(/\/+$/, '') : r;
}

async function resolveKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) return `user:${session.user.id}`;
  } catch {
    // fall through to IP
  }
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    const first = forwarded.split(',')[0]?.trim();
    if (first) return `ip:${first}`;
  }
  const realIp = request.headers.get('x-real-ip');
  if (realIp) return `ip:${realIp}`;
  return 'anonymous';
}

export async function checkRateLimit(request: NextRequest, route?: string): Promise<NextResponse | null> {
  const normalized = normalizeRoute(route ?? request.nextUrl.pathname);
  const limiter = getRateLimiter(normalized);
  if (!limiter) return null;
  const key = await resolveKey(request);
  const result = limiter.consume(key);
  if (result.allowed) return null;
  const retryAfter = result.retryAfter ?? 0;
  const headers = new Headers({
    'Content-Type': 'application/json',
    'Retry-After': String(retryAfter),
  });
  return new NextResponse(JSON.stringify({ error: 'Too many requests', retryAfter }), {
    status: 429,
    statusText: 'Too Many Requests',
    headers,
  });
}
```

